inventories={mode:artifact(aid,mode+'.json') for mode,aid in [('DEMO_SIMULATION',11998406630),('DISPOSABLE_TEST',11998247784),('UAT_AUTH_SIMULATION',11998077978)]}
menus=[]
for m in menu_data:
    page=m['page'];component,diff,positive,limit=D[page]
    assert (ROOT/'src'/component).exists(),component
    row=dict(**m,component='src/'+component,source_sha256=hashlib.sha256((ROOT/'src'/component).read_bytes()).hexdigest(),
             specific_difference=diff,positive_browser_case_ids=positive,boundary=limit,modes={})
    for mode,route in [('DISPOSABLE_TEST',m['disposable_route']),('UAT_AUTH_SIMULATION',m['uat_route'])]:
        current={vp:inventories[mode]['cases'][f'{mode}/{vp}/{page}'] for vp in ['desktop','phone']}
        demo={vp:inventories['DEMO_SIMULATION']['cases'][f'DEMO_SIMULATION/{vp}/{page}'] for vp in ['desktop','phone']}
        row['modes'][mode]=dict(route=route,comparison='BEDA' if route in ['CONNECTED','NOTICE'] else 'TIDAK ADA LAYAR TERSAMBUNG',
          data_origin='NATIVE_RPC_REQUIRED; inventory deliberately 403' if route=='CONNECTED' else 'LOCAL_EXAMPLE_DATA' if route=='SIMULATION' else 'NO_NUMBERS_OR_ACTIVE_TRANSACTION',
          current_inventory={vp:{k:current[vp][k] for k in ['status','inputs','buttons','rpc','simulation_label','money_strings','document_width','overflow_elements','page_errors']} for vp in current},
          demo_inventory={vp:{k:demo[vp][k] for k in ['inputs','buttons','simulation_label','document_width','overflow_elements']} for vp in demo},
          phone_proof='Chromium viewport 390x844; inventory/refusal only. Real Native positive phone cases only where separately listed for DISPOSABLE_TEST.',
          native_positive_browser_this_round=bool(positive) and mode=='DISPOSABLE_TEST',
          claim_limit='Inventory PASS means page visited and observations captured, not Native feature acceptance; UAT Auth/access are mocked and hosted is never contacted.')
    menus.append(row)
save('MENU_MATRIX.json',dict(candidate_sha=CANDIDATE,denominator=48,reviewed=48,inventory_visits=288,
    inventory_modes=['DEMO_SIMULATION','DISPOSABLE_TEST','UAT_AUTH_SIMULATION'],mock_business_status=403,hosted_requests=0,
    feature_acceptance_from_inventory=False,rows=menus))
with (OUT/'MENU_MATRIX.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['page','menu','DISPOSABLE_route','UAT_route','DISPOSABLE_comparison','UAT_comparison','difference','positive_browser_case_ids','boundary'])
    for r in menus:w.writerow([r['page'],r['label'],r['disposable_route'],r['uat_route'],r['modes']['DISPOSABLE_TEST']['comparison'],r['modes']['UAT_AUTH_SIMULATION']['comparison'],r['specific_difference'],'; '.join(r['positive_browser_case_ids']),r['boundary']])
md=['# Matriks 48 menu — Sol', '', 'Kandidat `'+CANDIDATE+'`. Semua 48 menu diperiksa pada kedua mode, dibanding demo; 288 kunjungan Chromium = 3 mode × 48 × 2 ukuran layar. **Auth/access tiruan, semua RPC bisnis 403** pada inventory ini. Saksi browser Native positif berasal dari run F03/CP17 yang dicatat terpisah, hanya build DISPOSABLE_TEST. Tidak ada SQL/permintaan hosted.', '', 'T = tersambung; D = data contoh; B = batas belum aktif; N = pemberitahuan. Setiap T/N dinilai **BEDA** dari demo sesuai perilaku kolom akhir; D/B = **TIDAK ADA LAYAR TERSAMBUNG**. BEDA mencakup penjagaan yang memang diwajibkan, bukan selalu bug.', '', '| Menu | DISPOSABLE | UAT/Enteng | Perilaku dan batas |','|---|---|---|---|']
short={'CONNECTED':'T','SIMULATION':'D','BLOCKED':'B','NOTICE':'N'}
for r in menus:md.append('| '+r['label']+' | '+short[r['disposable_route']]+' | '+short[r['uat_route']]+' | '+(r['specific_difference']+' '+r['boundary']).replace('|','/')+' |')
md+=['','UAT: **23 T, 23 D, 1 B, 1 N**. DISPOSABLE: **35 T, 12 D, 1 N**. Jumlah ini rute sumber + observasi browser, bukan persentase fitur siap pakai. JSON menyimpan isian/tombol/RPC aktual, perbedaan, sumber, saksi positif dan batas masing-masing menu. Nilai `viewport` mentah berupa angka 1440/390 karena metadata tertimpa `innerWidth`; nama desktop/phone tetap terikat ID kasus.','']
(OUT/'MENU_MATRIX.md').write_text('\n'.join(md))

